import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
void main() => runApp(const MaterialApp(home: ProductStorePage(), debugShowCheckedModeBanner: false));
class Product { final int id; final String title, description, image; final double price; final String category; const Product({required this.id, required this.title, required this.description, required this.image, required this.price, required this.category}); factory Product.fromJson(Map<String, dynamic> j) => Product(id: j['id'] as int, title: j['title'] as String, description: j['description'] as String, image: j['image'] as String, price: (j['price'] as num).toDouble(), category: j['category'] as String); }
Future<List<Product>> fetchProducts() async { final r = await http.get(Uri.parse('https://fakestoreapi.com/products')); if (r.statusCode != 200) throw Exception('HTTP ${r.statusCode}'); return (jsonDecode(r.body) as List).map((e) => Product.fromJson(e as Map<String, dynamic>)).toList(); }
class ProductStorePage extends StatefulWidget { const ProductStorePage({super.key}); @override State<ProductStorePage> createState() => _ProductStorePageState(); }
class _ProductStorePageState extends State<ProductStorePage> { late Future<List<Product>> products; @override void initState() { super.initState(); products = fetchProducts(); } void retry() => setState(() => products = fetchProducts()); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Q15: Product Store')), body: FutureBuilder<List<Product>>(future: products, builder: (context, s) { if (s.connectionState == ConnectionState.waiting) return const Center(child: CircularProgressIndicator()); if (s.hasError) return Center(child: Column(mainAxisSize: MainAxisSize.min, children: [Text('Could not load products: ${s.error}'), const SizedBox(height: 8), FilledButton(onPressed: retry, child: const Text('Retry'))])); final list = s.data!; return GridView.builder(padding: const EdgeInsets.all(10), gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: 2, childAspectRatio: .62, crossAxisSpacing: 10, mainAxisSpacing: 10), itemCount: list.length, itemBuilder: (context, i) { final p = list[i]; return Card(clipBehavior: Clip.antiAlias, child: InkWell(onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => ProductDetailPage(product: p))), child: Padding(padding: const EdgeInsets.all(10), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Expanded(child: Center(child: Image.network(p.image, fit: BoxFit.contain, errorBuilder: (_, __, ___) => const Icon(Icons.broken_image, size: 50), loadingBuilder: (context, child, progress) => progress == null ? child : const Center(child: CircularProgressIndicator())))), const SizedBox(height: 8), Text(p.title, maxLines: 2, overflow: TextOverflow.ellipsis, style: const TextStyle(fontWeight: FontWeight.w600)), const SizedBox(height: 5), Text('\$${p.price.toStringAsFixed(2)}', style: const TextStyle(fontSize: 16)), Text(p.category, maxLines: 1, overflow: TextOverflow.ellipsis, style: Theme.of(context).textTheme.bodySmall)])))); }); }));
}
class ProductDetailPage extends StatelessWidget { final Product product; const ProductDetailPage({super.key, required this.product}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Product details')), body: ListView(padding: const EdgeInsets.all(16), children: [SizedBox(height: 280, child: Image.network(product.image, fit: BoxFit.contain, errorBuilder: (_, __, ___) => const Icon(Icons.broken_image, size: 64), loadingBuilder: (context, child, progress) => progress == null ? child : const Center(child: CircularProgressIndicator()))), const SizedBox(height: 16), Text(product.title, style: Theme.of(context).textTheme.titleLarge), const SizedBox(height: 8), Text('\$${product.price.toStringAsFixed(2)}', style: Theme.of(context).textTheme.headlineSmall), Text('Category: ${product.category}'), const Divider(), Text(product.description)])); }
